    internal static string Get(string name, IconVariant variant) => Resolve(name, variant).Content;
    internal static int GetViewBoxSize(string name, IconVariant variant) => Resolve(name, variant).ViewBoxSize;

    private static IconData Resolve(string name, IconVariant variant)
    {
        var key = $"{variant}:{name}";
        if (Paths.TryGetValue(key, out var data)) return data;
        if (variant != IconVariant.Regular && Paths.TryGetValue($"{IconVariant.Regular}:{name}", out data)) return data;
        return Default;
    }
}
